import sqlite3, threading, time


def test_enroll_code_exchanged_twice_when_requests_overlap(appenv, monkeypatch):
    store = appenv.store
    store.create_wearer('alice', 'Alice')
    code_hash = appenv.wearers.hash_token('ABCDEFGH')
    store.create_enroll_code('alice', code_hash, time.time() + 3600)
    barrier = threading.Barrier(2, timeout=15)

    class Proxy:  # wraps sqlite3.Connection; parks both callers after their SELECT
        def __init__(self, conn):
            object.__setattr__(self, '_c', conn)
        def __getattr__(self, name):
            return getattr(self._c, name)
        def __setattr__(self, name, value):
            setattr(self._c, name, value)
        def __enter__(self):
            self._c.__enter__()
            return self
        def __exit__(self, *exc):
            return self._c.__exit__(*exc)
        def execute(self, sql, *args):
            if sql.lstrip().startswith('UPDATE enroll_codes'):
                barrier.wait()  # both SELECTs have run before either UPDATE
            return self._c.execute(sql, *args)

    real_connect = sqlite3.connect
    monkeypatch.setattr(sqlite3, 'connect', lambda *a, **k: Proxy(real_connect(*a, **k)))
    results = []

    def worker(i):
        results.append(store.exchange_enroll_code(code_hash, time.time(), 'tok%d' % i))

    threads = [threading.Thread(target=worker, args=(i,)) for i in range(2)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(60)
    n = real_connect(store.path).execute(
        'SELECT COUNT(*) FROM tokens WHERE wearer_id=?', ('alice',)).fetchone()[0]
    # current source: both calls succeed and two live tokens exist for one code
    assert results == ['alice', 'alice'] and n == 2
